CREATE FUNCTION public.protect_workspace_security() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN RAISE EXCEPTION 'Workspace ownership cannot be changed'; END IF; IF NEW.paused IS DISTINCT FROM OLD.paused AND NOT public.has_role(auth.uid(), 'admin') AND auth.role() <> 'service_role' THEN RAISE EXCEPTION 'Only administrators can change platform pause state'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_workspace_security BEFORE UPDATE ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.protect_workspace_security();